export function getRecommendations(assessment, context) {
  return assessment.factors.filter(f => f.contribution > 0).sort((a, b) => Number(b.critical) - Number(a.critical) || b.contribution - a.contribution).map(f => ({ ...guidance[f.id], ...f, title: guidance[f.id].title, steps: guidance[f.id].steps(context), verification: guidance[f.id].verification }));
}

export function contextAdvice(context) {
  const purpose = PURPOSES.find(p => p.id === context.purpose);
  const messages = [PLACES.find(p => p.id === context.place).tip];
  if (context.purpose === 'work') messages.push('Для рабочих документов соблюдайте политику организации. Если публичный Wi-Fi запрещён, выберите разрешённое подключение независимо от балла. Не устанавливайте корпоративные профили без указания ИТ-службы.');
  if (context.purpose === 'personal') messages.push('Проверяйте домен сайта, используйте разные пароли и многофакторную аутентификацию. VPN не защищает от передачи пароля мошеннику.');
  if (context.purpose === 'browse') messages.push('Для обычного просмотра сайтов проверяйте HTTPS и адрес. Не соглашайтесь на неожиданную установку расширений, сертификатов и приложений.');
  if (context.device === 'windows') messages.push('Для общественного Wi-Fi оставьте профиль Windows «Общедоступная сеть» и не включайте обнаружение и общий доступ. Этот дополнительный совет не входит в балл опроса.');
  return { label: `${PLACES.find(p => p.id === context.place).name} · ${DEVICES.find(d => d.id === context.device).name} · ${purpose.name}`, messages };
}
